const { Given, When, Then } = require('@cucumber/cucumber');

// Helper
function addTodo(world, title) {
  const input = world.document.querySelector('.new-todo');
  if (!input) throw new Error('Could not find .new-todo input');
  input.value = title;
  input.dispatchEvent(new world.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new world.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
}

function findTodoLi(world, title) {
  const todos = world.document.querySelectorAll('.todo-list li');
  for (const li of todos) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) return li;
  }
  return null;
}

function isVisible(world, el) {
  if (!el) return false;
  if (el.style.display === 'none') return false;
  const style = world.window.getComputedStyle(el);
  return style.display !== 'none';
}

// --- Given ---

Given('the app is loaded', function () {
  // Handled by Before hook in world.js
});

Given('there are no todos', function () {
  const todos = this.document.querySelectorAll('.todo-list li');
  if (todos.length > 0) {
    throw new Error('Expected no todos but found ' + todos.length);
  }
});

Given('a todo {string} exists', function (title) {
  addTodo(this, title);
});

Given('todos {string}, {string} exist', function (t1, t2) {
  addTodo(this, t1);
  addTodo(this, t2);
});

Given('todos {string}, {string}, {string} exist', function (t1, t2, t3) {
  addTodo(this, t1);
  addTodo(this, t2);
  addTodo(this, t3);
});

Given('a todo {string} that is completed', function (title) {
  addTodo(this, title);
  const li = findTodoLi(this, title);
  if (li) {
    li.classList.add('completed');
    const cb = li.querySelector('.toggle');
    if (cb) { cb.checked = true; cb.dispatchEvent(new this.window.Event('change', { bubbles: true })); }
  }
});

Given('{string} is completed', function (title) {
  const li = findTodoLi(this, title);
  if (li) {
    li.classList.add('completed');
    const cb = li.querySelector('.toggle');
    if (cb) { cb.checked = true; cb.dispatchEvent(new this.window.Event('change', { bubbles: true })); }
  }
});

Given('the new todo input is focused', function () {
  const input = this.document.querySelector('.new-todo');
  if (!input) throw new Error('Could not find .new-todo input');
  input.focus();
});

Given('I am editing {string}', function (title) {
  addTodo(this, title);
  const li = findTodoLi(this, title);
  if (li) {
    li.classList.add('editing');
    const editInput = li.querySelector('.edit');
    if (editInput) { editInput.value = title; editInput.focus(); }
  }
});

Given('I am on the {string} filter', function (filter) {
  this.navigate(filter);
});

// --- When ---

When('I type {string} into the new todo input', function (text) {
  const input = this.document.querySelector('.new-todo');
  if (!input) throw new Error('Could not find .new-todo input');
  input.value = text;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('I press Enter', function () {
  const input = this.document.querySelector('.new-todo');
  if (!input) throw new Error('Could not find .new-todo input');
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('I click the checkbox for {string}', function (title) {
  const li = findTodoLi(this, title);
  if (!li) throw new Error('Could not find todo "' + title + '"');
  const cb = li.querySelector('.toggle');
  if (!cb) throw new Error('No checkbox for "' + title + '"');
  cb.checked = !cb.checked;
  cb.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('I click the {string} toggle', function (toggleLabel) {
  const toggle = this.document.getElementById('toggle-all');
  if (!toggle) throw new Error('Could not find toggle-all');
  toggle.checked = !toggle.checked;
  toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('I click {string}', function (text) {
  const buttons = this.document.querySelectorAll('button, a, .clear-completed');
  for (const el of buttons) {
    if (el.textContent.trim() === text) {
      el.click();
      return;
    }
  }
  throw new Error('Could not find element with text "' + text + '"');
});

When('I double-click the label of {string}', function (title) {
  const li = findTodoLi(this, title);
  if (!li) throw new Error('Could not find todo "' + title + '"');
  const label = li.querySelector('label');
  if (!label) throw new Error('No label for "' + title + '"');
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When('I change the value to {string}', function (text) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No editing input found');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('the edit input loses focus', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No editing input found');
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('I press Enter in the edit input', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No editing input found');
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('I clear the edit input', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No editing input found');
  editInput.value = '';
  editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('I press Escape in the edit input', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No editing input found');
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
});

When('I click the destroy button for {string}', function (title) {
  const li = findTodoLi(this, title);
  if (!li) throw new Error('Could not find todo "' + title + '"');
  const destroy = li.querySelector('.destroy');
  if (!destroy) throw new Error('No destroy button for "' + title + '"');
  destroy.click();
});

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

When('I reload the app', function () {
  const data = this.localStorage.getItem('todos-vanilla');
  const hash = this.window.location.hash;
  return this.disposeApp().then(() => {
    this.loadApp();
    // loadApp already ran the app code which called render() with empty localStorage.
    // Restore data and hash, then re-render via hashchange so the UI reflects saved state.
    if (data) {
      this.localStorage.setItem('todos-vanilla', data);
    }
    if (hash) {
      this.window.location.hash = hash;
    }
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  });
});

// --- Then ---

Then('{string} is not visible', function (selector) {
  const el = this.document.querySelector(selector);
  if (!el) throw new Error('Could not find "' + selector + '"');
  if (isVisible(this, el)) {
    const parent = el.closest('section');
    if (!parent || isVisible(this, parent)) {
      throw new Error('Expected "' + selector + '" to not be visible');
    }
  }
});

Then('{string} is not visible in the list', function (title) {
  const li = findTodoLi(this, title);
  if (li && isVisible(this, li)) {
    throw new Error('Expected "' + title + '" to not be visible in the list');
  }
});

Then('a new todo {string} appears in the list', function (title) {
  if (!findTodoLi(this, title)) {
    throw new Error('Expected todo "' + title + '" to appear in the list');
  }
});

Then('the new todo input is cleared', function () {
  const input = this.document.querySelector('.new-todo');
  if (!input) throw new Error('Could not find .new-todo input');
  if (input.value !== '') throw new Error('Expected input to be cleared but got "' + input.value + '"');
});

Then('no new todo is created', function () {
  const todos = this.document.querySelectorAll('.todo-list li');
  if (todos.length > 0) throw new Error('Expected no todos, found ' + todos.length);
});

Then('{string} is marked as completed', function (title) {
  const li = findTodoLi(this, title);
  if (!li) throw new Error('Could not find todo "' + title + '"');
  if (!li.classList.contains('completed')) throw new Error('Expected "' + title + '" to be completed');
  const cb = li.querySelector('.toggle');
  if (cb && !cb.checked) throw new Error('Expected checkbox for "' + title + '" to be checked');
});

Then('the {string} class is added to its <li>', function (className) {
  const todos = this.document.querySelectorAll('.todo-list li');
  let hasClass = false;
  for (const li of todos) {
    if (li.classList.contains(className)) { hasClass = true; break; }
  }
  if (!hasClass) throw new Error('Expected some li to have class "' + className + '"');
});

Then('{string} is marked as active', function (title) {
  const li = findTodoLi(this, title);
  if (!li) throw new Error('Could not find todo "' + title + '"');
  if (li.classList.contains('completed')) throw new Error('Expected "' + title + '" to not be completed');
  const cb = li.querySelector('.toggle');
  if (cb && cb.checked) throw new Error('Expected checkbox for "' + title + '" to not be checked');
});

Then('all todos are marked as completed', function () {
  const todos = this.document.querySelectorAll('.todo-list li');
  for (const li of todos) {
    if (!li.classList.contains('completed')) throw new Error('Expected all todos to be completed');
  }
});

Then('the toggle-all checkbox is checked', function () {
  const toggle = this.document.getElementById('toggle-all');
  if (!toggle) throw new Error('Could not find toggle-all');
  if (!toggle.checked) throw new Error('Expected toggle-all to be checked');
});

Then('the toggle-all checkbox is not checked', function () {
  const toggle = this.document.getElementById('toggle-all');
  if (!toggle) throw new Error('Could not find toggle-all');
  if (toggle.checked) throw new Error('Expected toggle-all to not be checked');
});

Then('the edit input for {string} is shown', function (title) {
  const li = findTodoLi(this, title);
  if (!li) throw new Error('Could not find todo "' + title + '"');
  if (!li.classList.contains('editing')) throw new Error('Expected "' + title + '" to be editing');
  const editInput = li.querySelector('.edit');
  if (!editInput) throw new Error('No edit input for "' + title + '"');
  if (!isVisible(this, editInput)) throw new Error('Expected edit input for "' + title + '" to be shown');
});

Then('the edit input is focused', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No editing input found');
  if (this.document.activeElement !== editInput) {
    throw new Error('Expected edit input to be focused');
  }
});

Then('the todo is updated to {string}', function (title) {
  if (!findTodoLi(this, title)) {
    throw new Error('Expected todo "' + title + '" to exist');
  }
  const editing = this.document.querySelector('.todo-list li.editing');
  if (editing) throw new Error('Expected editing mode to be closed');
});

Then('the {string} class is removed', function (className) {
  const todos = this.document.querySelectorAll('.todo-list li');
  for (const li of todos) {
    if (li.classList.contains(className)) {
      throw new Error('Expected no li to have class "' + className + '"');
    }
  }
});

Then('the todo {string} is removed', function (title) {
  if (findTodoLi(this, title)) {
    throw new Error('Expected todo "' + title + '" to be removed');
  }
});

Then('the todo is still {string}', function (title) {
  if (!findTodoLi(this, title)) {
    throw new Error('Expected todo "' + title + '" to still exist');
  }
});

Then('the todo count shows {string} items left', function (count) {
  const strong = this.document.querySelector('.todo-count strong');
  if (!strong) throw new Error('Could not find .todo-count strong');
  if (strong.textContent !== count) {
    throw new Error('Expected todo count "' + count + '" but got "' + strong.textContent + '"');
  }
});

Then('the todo count shows {string} item left', function (count) {
  const strong = this.document.querySelector('.todo-count strong');
  if (!strong) throw new Error('Could not find .todo-count strong');
  if (strong.textContent !== count) {
    throw new Error('Expected todo count "' + count + '" but got "' + strong.textContent + '"');
  }
});

Then('the todo {string} remains', function (title) {
  if (!findTodoLi(this, title)) {
    throw new Error('Expected todo "' + title + '" to remain');
  }
});

Then('the {string} button is not visible', function (text) {
  const buttons = this.document.querySelectorAll('button');
  for (const btn of buttons) {
    if (btn.textContent.trim() === text) {
      if (isVisible(this, btn)) {
        const parent = btn.closest('section, footer');
        if (!parent || isVisible(this, parent)) {
          throw new Error('Expected "' + text + '" button to not be visible');
        }
      }
      return;
    }
  }
});

Then('the todo {string} appears in the list', function (title) {
  if (!findTodoLi(this, title)) {
    throw new Error('Expected todo "' + title + '" to appear in the list');
  }
});

Then('the todo {string} is not in edit mode', function (title) {
  const li = findTodoLi(this, title);
  if (!li) throw new Error('Could not find todo "' + title + '"');
  if (li.classList.contains('editing')) throw new Error('Expected "' + title + '" to not be in edit mode');
});

Then('I see {int} todos in the list', function (count) {
  const todos = this.document.querySelectorAll('.todo-list li');
  if (todos.length !== count) {
    throw new Error('Expected ' + count + ' todos but found ' + todos.length);
  }
});

Then('I see {int} todo in the list', function (count) {
  const todos = this.document.querySelectorAll('.todo-list li');
  if (todos.length !== count) {
    throw new Error('Expected ' + count + ' todo but found ' + todos.length);
  }
});

Then('the {string} filter link has the {string} class', function (filterText, className) {
  const links = this.document.querySelectorAll('.filters a');
  for (const a of links) {
    if (a.textContent.trim() === filterText) {
      if (!a.classList.contains(className)) {
        throw new Error('Expected "' + filterText + '" link to have class "' + className + '"');
      }
      return;
    }
  }
  throw new Error('Could not find filter link "' + filterText + '"');
});

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

/* global localStorage */
var ENTER_KEY = 13;
var ESCAPE_KEY = 27;

(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanilla';

  // --- Model ---

  function getTodos() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      return [];
    }
  }

  function saveTodos(todos) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function nextId() {
    var todos = getTodos();
    var max = 0;
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id > max) max = todos[i].id;
    }
    return max + 1;
  }

  // --- View ---

  var todoapp = document.querySelector('.todoapp');
  var newTodoInput = document.querySelector('.new-todo');
  var todoList = document.querySelector('.todo-list');
  var toggleAll = document.getElementById('toggle-all');
  var clearCompleted = document.querySelector('.clear-completed');
  var todoCountStrong = document.querySelector('.todo-count strong');
  var filters = document.querySelectorAll('.filters a');

  var currentFilter = 'all';

  function render() {
    var todos = getTodos();
    var filtered = filterTodos(todos, currentFilter);
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var completedCount = todos.length - activeCount;

    // Toggle main/footer visibility
    if (todos.length > 0) {
      todoapp.classList.add('has-todos');
    } else {
      todoapp.classList.remove('has-todos');
    }

    // Render list
    todoList.innerHTML = '';
    filtered.forEach(function (todo) {
      var li = document.createElement('li');
      if (todo.completed) li.classList.add('completed');

      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">';

      var checkbox = li.querySelector('.toggle');
      checkbox.addEventListener('change', function () {
        todo.completed = checkbox.checked;
        saveTodos(todos);
        render();
      });

      var label = li.querySelector('label');
      label.addEventListener('dblclick', function () {
        li.classList.add('editing');
        var editInput = li.querySelector('.edit');
        editInput.focus();
        editInput.value = todo.title;
      });

      var editInput = li.querySelector('.edit');
      editInput.addEventListener('blur', function () {
        commitEdit(li, todo, editInput, todos);
      });
      editInput.addEventListener('keydown', function (e) {
        if (e.keyCode === ENTER_KEY) {
          commitEdit(li, todo, editInput, todos);
        } else if (e.keyCode === ESCAPE_KEY) {
          li.classList.remove('editing');
          editInput.value = todo.title;
        }
      });

      var destroyBtn = li.querySelector('.destroy');
      destroyBtn.addEventListener('click', function () {
        var idx = todos.indexOf(todo);
        if (idx !== -1) todos.splice(idx, 1);
        saveTodos(todos);
        render();
      });

      todoList.appendChild(li);
    });

    // Update toggle-all
    toggleAll.checked = activeCount === 0 && todos.length > 0;

    // Update count
    todoCountStrong.textContent = String(activeCount);
    var word = activeCount === 1 ? 'item' : 'items';
    var textNode = todoCountStrong.nextSibling;
    if (textNode) textNode.textContent = ' ' + word + ' left';

    // Update clear completed
    if (completedCount > 0) {
      clearCompleted.classList.remove('hidden');
    } else {
      clearCompleted.classList.add('hidden');
    }

    // Update filter links
    filters.forEach(function (a) {
      a.classList.remove('selected');
      if (a.hash === '#/' && currentFilter === 'all') a.classList.add('selected');
      if (a.hash === '#/active' && currentFilter === 'active') a.classList.add('selected');
      if (a.hash === '#/completed' && currentFilter === 'completed') a.classList.add('selected');
    });
  }

  function commitEdit(li, todo, editInput, todos) {
    var val = editInput.value.trim();
    if (val === '') {
      var idx = todos.indexOf(todo);
      if (idx !== -1) todos.splice(idx, 1);
    } else {
      todo.title = val;
    }
    li.classList.remove('editing');
    saveTodos(todos);
    render();
  }

  function filterTodos(todos, filter) {
    if (filter === 'active') return todos.filter(function (t) { return !t.completed; });
    if (filter === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(str));
    return div.innerHTML;
  }

  // --- Events ---

  newTodoInput.addEventListener('keydown', function (e) {
    if (e.keyCode !== ENTER_KEY) return;
    var val = newTodoInput.value.trim();
    newTodoInput.value = '';
    if (val === '') return;
    var todos = getTodos();
    todos.push({ id: nextId(), title: val, completed: false });
    saveTodos(todos);
    render();
  });

  toggleAll.addEventListener('change', function () {
    var todos = getTodos();
    var checked = toggleAll.checked;
    todos.forEach(function (t) { t.completed = checked; });
    saveTodos(todos);
    render();
  });

  clearCompleted.addEventListener('click', function () {
