// --- Event delegation on todoList ---
// Uses data-id to find the todo, avoiding stale closures from per-element handlers

todoList.addEventListener('change', function (e) {
  var target = e.target;
  if (!target.classList.contains('toggle')) return;
  var li = target.closest('li');
  if (!li) return;
  var id = li.getAttribute('data-id');
  if (id === null) return;
  var todos = getTodos();
  for (var i = 0; i < todos.length; i++) {
    if (String(todos[i].id) === id) {
      todos[i].completed = target.checked;
      break;
    }
  }
  saveTodos(todos);
  render();
});

todoList.addEventListener('click', function (e) {
  var target = e.target;
  if (target.classList.contains('destroy')) {
    var li = target.closest('li');
    if (!li) return;
    var id = li.getAttribute('data-id');
    if (id === null) return;
    var todos = getTodos();
    for (var i = 0; i < todos.length; i++) {
      if (String(todos[i].id) === id) {
        todos.splice(i, 1);
        break;
      }
    }
    saveTodos(todos);
    render();
  }
});

todoList.addEventListener('dblclick', function (e) {
  var target = e.target;
  if (target.tagName !== 'LABEL') return;
  var li = target.closest('li');
  if (!li) return;
  var id = li.getAttribute('data-id');
  if (id === null) return;
  var todos = getTodos();
  var todo = null;
  for (var i = 0; i < todos.length; i++) {
    if (String(todos[i].id) === id) {
      todo = todos[i];
      break;
    }
  }
  if (!todo) return;
  li.classList.add('editing');
  var editInput = li.querySelector('.edit');
  editInput.focus();
  editInput.value = todo.title;
});

todoList.addEventListener('blur', function (e) {
  var target = e.target;
  if (!target.classList.contains('edit')) return;
  var li = target.closest('li');
  if (!li) return;
  var id = li.getAttribute('data-id');
  if (id === null) return;
  var todos = getTodos();
  var todo = null;
  for (var i = 0; i < todos.length; i++) {
    if (String(todos[i].id) === id) {
      todo = todos[i];
      break;
    }
  }
  if (!todo) return;
  commitEditDelegate(li, todo, target, todos);
}, true);

todoList.addEventListener('keydown', function (e) {
  var target = e.target;
  if (!target.classList.contains('edit')) return;
  var li = target.closest('li');
  if (!li) return;
  var id = li.getAttribute('data-id');
  if (id === null) return;
  var todos = getTodos();
  var todo = null;
  for (var i = 0; i < todos.length; i++) {
    if (String(todos[i].id) === id) {
      todo = todos[i];
      break;
    }
  }
  if (!todo) return;
  if (e.keyCode === ENTER_KEY) {
    commitEditDelegate(li, todo, target, todos);
  } else if (e.keyCode === ESCAPE_KEY) {
    li.classList.remove('editing');
    target.value = todo.title;
  }
});

function commitEditDelegate(li, todo, editInput, todos) {
